let vh = window.innerHeight * 0.01;
// Then we set the value in the --vh custom property to the root of the document
document.documentElement.style.setProperty('--vh', `${vh}px`);

// We listen to the resize event
window.addEventListener('resize', () => {
	// We execute the same script as before
	let vh = window.innerHeight * 0.01;
	document.documentElement.style.setProperty('--vh', `${vh}px`);
});
function getCookie(name) {
	let matches = document.cookie.match(new RegExp(
		"(?:^|; )" + name.replace(/([\.$?*|{}\(\)\[\]\\\/\+^])/g, '\\$1') + "=([^;]*)"
	));
	return matches ? decodeURIComponent(matches[1]) : undefined;
}
function setCookie(name, value, options = {}) {

	if (options.expires instanceof Date) {
		options.expires = options.expires.toUTCString();
	}
	let updatedCookie = encodeURIComponent(name) + "=" + encodeURIComponent(value);

	for (let optionKey in options) {
		updatedCookie += "; " + optionKey;
		let optionValue = options[optionKey];
		if (optionValue !== true) {
			updatedCookie += "=" + optionValue;
		}
	}

	document.cookie = updatedCookie;
}
function validateEmail(email){
	let email_string = /^(([^<>()[\]\\.,;:\s@\"]+(\.[^<>()[\]\\.,;:\s@\"]+)*)|(\".+\"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$/;
	if(email.match(email_string)){
		return true;
	}else {
		return false;
	}

}
function validatePhone(phone){
	let letters =/[a-zA-Z\/\\\*\%\$\|\#\@\'\"\:\;\&\?\.\,\<\>]/g;
	if(phone.match(letters)){
		return false;
	}
	else{
		return true ;
	}
}
// faq content nav
let faqContent = document.querySelectorAll(".faq-content");
if (faqContent.length > 0) {
	const navList = document.querySelector('.text-nav-list');
	const navLinks = document.querySelectorAll(".text-content h3");
	let navListArrey = [];
	let isScrollingDisabled = false;
	navLinks.forEach((heading, index) => {
		const id = "section-" + (index + 1);
		heading.setAttribute("id", id);
		const listItem = document.createElement("li");
		const navItem = document.createElement("button");
		navItem.setAttribute("data-id", id);
		navItem.setAttribute("class", 'text-nav-item');
		const navItemMore = document.createElement("span");
		navItem.textContent = heading.textContent;
		navItem.appendChild(navItemMore);
		listItem.appendChild(navItem);
		navList.appendChild(listItem);
		navItem.addEventListener('click', function (e) {
			isScrollingDisabled = true;
			window.scrollTo({
				top: navLinks[index].getBoundingClientRect().top + window.scrollY - document.querySelector('.header-group').offsetHeight,
				behavior: 'smooth'
			});
			navListArrey.forEach(item => item.classList.remove('active'));
			navItem.classList.add('active');
			setTimeout(() => {
				isScrollingDisabled = false;
			}, 1000);
		});
	});
	navListArrey = navList.querySelectorAll('.text-nav-item');
	navListArrey[0].classList.add('active');
	window.addEventListener('scroll', () => {
		if (isScrollingDisabled) return;
		let current = "";
		navLinks.forEach((heading, index) => {
			const sectionTop = heading.offsetTop - document.querySelector('.header-group')?.offsetHeight + 65;
			if (window.scrollY >= sectionTop) {
				current = heading.getAttribute("id");
			}
		});
		navListArrey.forEach(navItem => {
			navItem.classList.remove('active');
			if (navItem.getAttribute("data-id") === current) {
				navItem.classList.add('active');
			}
		});
	});
}
