function addressesCount(){
	if(document.querySelector('.js-address-section')){
		let addressesCount = parseInt(document.querySelector('.js-address-section').dataset.addressesCount),
			addressesAccount = parseInt(document.querySelector('.js-address-section').dataset.addressesAccount);
		let previousAddressesCount = localStorage.getItem('addressesCount');
		let previousAddressesAccount = localStorage.getItem('addressesAccount');
		if(previousAddressesAccount){
			if(previousAddressesAccount != addressesAccount){
				localStorage.setItem('addressesCount', `${addressesCount}`);
				previousAddressesCount = addressesCount;
				localStorage.setItem('addressesAccount', `${addressesAccount}`);
			}else{
				localStorage.setItem('addressesAccount', `${addressesAccount}`);
			}
		}else{
			localStorage.setItem('addressesAccount', `${addressesAccount}`);
		}
		if(previousAddressesCount){
			if(parseInt(previousAddressesCount) > addressesCount){
				localStorage.setItem('addressesCount', `${addressesCount}`);
				if(document.querySelector('.js-addresses-notification')){
					document.querySelector('.js-addresses-notification').classList.add('show')
					setTimeout(function (){
						document.querySelector('.js-addresses-notification').classList.remove('show')
					},10000)
				}
			}else{
				localStorage.setItem('addressesCount', `${addressesCount}`);
			}
		}else{
			localStorage.setItem('addressesCount', `${addressesCount}`);
		}

	}
}
