//date-counter

let counterEl = document.querySelector('.vault-coutner');
const formatNumber = number => {
	return number < 10 ? `0${number}` : `${number}`;
};
if (counterEl) {
	const counterElValue = counterEl.getAttribute('data-counter');
	const countdownDate = new Date(counterElValue).getTime();
	const updateCountdown = () => {
		const now = new Date().getTime();
		const distance = countdownDate - now;
		const days = Math.floor(distance / (1000 * 60 * 60 * 24));
		const hours = Math.floor(distance % (1000 * 60 * 60 * 24) / (1000 * 60 * 60));
		const minutes = Math.floor(distance % (1000 * 60 * 60) / (1000 * 60));
		const seconds = Math.floor(distance % (1000 * 60) / 1000);
		if(document.getElementById("days")){
			document.getElementById("days").textContent = formatNumber(days);
		}
		if(document.getElementById("hours")){
			document.getElementById("hours").textContent = formatNumber(hours);
		}
		if(document.getElementById("minutes")){
			document.getElementById("minutes").textContent = formatNumber(minutes);
		}

		if(document.getElementById("seconds")){
			document.getElementById("seconds").textContent = formatNumber(seconds);
		}
		if (distance < 0) {
			clearInterval(interval);
			counterEl.classList.add('hide');
			if(counterEl.closest('.vault-container').querySelector('.vault-intro__title')){
				if(counterEl.closest('.vault-container').querySelector('.vault-intro__title').dataset.successTitle){
					counterEl.closest('.vault-container').querySelector('.vault-intro__title').innerHTML = counterEl.closest('.vault-container').querySelector('.vault-intro__title').dataset.successTitle;
					counterEl.closest('.vault-container').querySelector('.vault-intro__title').classList.add('vault-intro__title-big')
				}
			}
		}
		if (!counterElValue) {
			clearInterval(interval);
			counterEl.classList.add('hide');
			if(counterEl.closest('.vault-container').querySelector('.vault-intro__title')){
				if(counterEl.closest('.vault-container').querySelector('.vault-intro__title').dataset.successTitle){
					counterEl.closest('.vault-container').querySelector('.vault-intro__title').innerHTML = counterEl.closest('.vault-container').querySelector('.vault-intro__title').dataset.successTitle;
					counterEl.closest('.vault-container').querySelector('.vault-intro__title').classList.add('vault-intro__title-big')
				}
			}
		}
	};
	const interval = setInterval(updateCountdown, 1000);
	updateCountdown();
}
