let productZoomContainer = document.querySelectorAll('.js-product-gallery-zoom .carousel-item');
let previousX = 0;
let previousY = 0;
if (productZoomContainer) {
	productZoomContainer.forEach(function (block) {
		block.addEventListener('click', function (event) {
			if (this.classList.contains('zoomed')) {
				block.classList.remove('zoomed');
				block.querySelector('img').removeAttribute('style');
                if(block.closest('.product-gallery-carousel').classList.contains('swiper-no-swiping')){
                  block.closest('.product-gallery-carousel').classList.remove('swiper-no-swiping');
                }
			} else {
				setTimeout(function () {
					starterPosition(event, block);
				}, 100);
				setTimeout(function () {
					block.classList.add('zoomed');
				}, 600);
              setTimeout(function (){
    				block.closest('.product-gallery-carousel').classList.add('swiper-no-swiping');
              },500)
			}
			

		});
		if (isTouchDevice()) {
			block.addEventListener('touchstart', function (event) {
				previousX = event.touches[0].clientX;
				previousY = event.touches[0].clientY;
			});
			block.addEventListener('touchmove', function (event) {
				toucheMove(event, block);
			});
		} else {
			block.addEventListener('mousemove', function (event) {
				mouseMove(event, block);
			});
			block.addEventListener('mouseleave', function (event) {
				block.classList.remove('zoomed');
				block.querySelector('img').removeAttribute('style');
				block.closest('.product-gallery-carousel').classList.remove('swiper-no-swiping');
			});
		}
	});
}
function mouseMove(e, block) {
	let image = block.querySelector('img');
	let blockWidth = block.offsetWidth;
	let blockHeight = block.offsetHeight;
	let imageHeight = image.clientHeight * 3;
	let imageWidth = image.clientWidth * 3;
	let x = e.layerX;
	let y = e.layerY;
	let imageTransformX = -1 * (x / blockWidth) * (imageWidth - blockWidth);
	let imageTransformY = -1 * (y / blockHeight) * (imageHeight - blockHeight);
	if (block.classList.contains('zoomed')) {
		image.setAttribute('style', `transform: translate(${imageTransformX}px,${imageTransformY}px) scale(3)`);
	}
}
function toucheMove(e, block) {
	if (block.classList.contains('zoomed')) {
		e.preventDefault();
		let image = block.querySelector('img');
		let blockWidth = block.offsetWidth;
		let blockHeight = block.offsetHeight;
		let imageHeight = image.clientHeight * 3;
		let imageWidth = image.clientWidth * 3;
		let x = e.touches[0].clientX;
		let y = e.touches[0].clientY;
		let tranclateX = parseInt(new WebKitCSSMatrix(window.getComputedStyle(image).transform).m41);
		let tranclateY = parseInt(new WebKitCSSMatrix(window.getComputedStyle(image).transform).m42);
		let imageTransformX;
		let imageTransformY;
		if (previousX > x) {
			imageTransformX = tranclateX - (previousX - x);
		} else if (previousX < x) {
			imageTransformX = tranclateX + Math.abs(previousX - x);
		}
		if (previousY > y) {
			imageTransformY = tranclateY - (previousY - y);
		} else if (previousY < y) {
			imageTransformY = tranclateY + Math.abs(previousY - y);
		}
		if (imageTransformX >= 0) {
			imageTransformX = 0;
		}
		if (imageTransformX < -1 * (imageWidth - blockWidth)) {
			imageTransformX = -1 * (imageWidth - blockWidth);
		}
		if (imageTransformY > 0) {
			imageTransformY = 0;
		}
		if (imageTransformY < -1 * (imageHeight - blockHeight)) {
			imageTransformY = -1 * (imageHeight - blockHeight);
		}
		if (imageTransformX != null && imageTransformY != null) {
			image.setAttribute('style', `transform: translate(${imageTransformX}px,${imageTransformY}px) scale(3)`);
		}
		previousX = x;
		previousY = y;
	}
}
function starterPosition(e, block) {
	let image = block.querySelector('img');
	let blockWidth = block.offsetWidth;
	let blockHeight = block.offsetHeight;
	let imageHeight = image.clientHeight * 3;
	let imageWidth = image.clientWidth * 3;
	let x = e.layerX;
	let y = e.layerY;
	if (isTouchDevice()) {
		x = e.clientX;
		y = e.clientY;
	}
	let imageTransformX = -1 * (x / blockWidth) * (imageWidth - blockWidth);
	let imageTransformY = -1 * (y / blockHeight) * (imageHeight - blockHeight);
	image.setAttribute('style', `transform: translate(${imageTransformX}px,${imageTransformY}px) scale(3)`);

}
function isTouchDevice() {
	return 'ontouchstart' in window || navigator.maxTouchPoints > 0 || navigator.msMaxTouchPoints > 0;
}
